require_once __DIR__.'/config.php'; require_once __DIR__.'/auth.php'; rts_require_login(); if(!rts_is_approver()){http_response_code(403);exit('Akses hanya untuk ADMIN atau ASS.');}
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_FILES['file_customer'])){ $f=$_FILES['file_customer']; if($f['error']!==UPLOAD_ERR_OK){$error='File gagal diupload.';} elseif($f['size']>10*1024*1024){$error='Ukuran file maksimal 10 MB.';} else {$h=fopen($f['tmp_name'],'r');$header=fgetcsv($h);$header=array_map(fn($x)=>strtolower(trim((string)$x)),$header?:[]);$required=['id_customer','nama_toko','tipe_customer','salesman','alamat','kunjungan','hari','sales_district','longitude','latitude','status_aktif'];$missing=array_diff($required,$header);if($missing){$error='Kolom tidak lengkap: '.implode(', ',$missing);}else{$count=0;$stmt=$conn->prepare('INSERT INTO master_toko (id_customer,nama_toko,tipe_customer,salesman,alamat,kunjungan,hari,sales_district,longitude,latitude,status_aktif) VALUES (?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE nama_toko=VALUES(nama_toko),tipe_customer=VALUES(tipe_customer),salesman=VALUES(salesman),alamat=VALUES(alamat),kunjungan=VALUES(kunjungan),hari=VALUES(hari),sales_district=VALUES(sales_district),longitude=VALUES(longitude),latitude=VALUES(latitude),status_aktif=VALUES(status_aktif)');while(($row=fgetcsv($h))!==false){$d=array_pad($row,count($header),'');$v=array_combine($header,$d);$type=strtoupper(trim($v['tipe_customer']));if(!in_array($type,['REGULER','GSP'],true))$type='REGULER';$status=trim($v['status_aktif'])==='Nonaktif'?'Nonaktif':'Aktif';$stmt->bind_param('sssssssssss',$v['id_customer'],$v['nama_toko'],$type,$v['salesman'],$v['alamat'],$v['kunjungan'],$v['hari'],$v['sales_district'],$v['longitude'],$v['latitude'],$status);if($stmt->execute())$count++;}fclose($h);$message="$count data customer berhasil diproses.";}}}
require_once __DIR__.'/header.php';?><div class="card border-0 shadow-sm" style="max-width:900px"><div class="card-body p-4"><h3>Upload Data Customer</h3><p class="text-muted">Khusus ADMIN/ASS. File harus CSV UTF-8 dengan header sesuai template.</p><?php if($message):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><a class="btn btn-outline-success mb-3" href="template_customer.csv" download>Download Template CSV</a><form method="post" enctype="multipart/form-data"><input type="file" name="file_customer" class="form-control mb-3" accept=".csv,text/csv" required><button class="btn btn-primary">Upload dan Update Data</button></form><hr><small class="text-muted">Jika ID Customer sudah ada, data akan diperbarui. Jika belum ada, data baru akan ditambahkan. Backup database testing sebelum upload massal.</small></div></div><?php require_once __DIR__.'/footer.php';?>
